-- =============================================================================
-- 074_growth_snapshots_seeds.sql
-- Snapshot library (GHL style snapshots), export / import, and org seeding.
-- Generated by tests/build_074.py. Edit the Python, not this file.
-- =============================================================================

create table if not exists public.fh_snapshot_library (
  key text primary key,
  vertical text not null,
  name text not null,
  snapshot jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.fh_snapshot_library enable row level security;
drop policy if exists fh_snapshot_library_read on public.fh_snapshot_library;
create policy fh_snapshot_library_read on public.fh_snapshot_library for select to authenticated using (true);
grant select on public.fh_snapshot_library to authenticated, service_role;
grant insert, update, delete on public.fh_snapshot_library to service_role;

-- payment link for merge fields
create or replace function public.fh_org_ctx(p_org_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_org record; v_prof record; v_set record; v_owner_name text;
begin
  select * into v_org from public.organizations where id = p_org_id;
  select * into v_set from public.fh_org_settings where org_id = p_org_id;
  select p.* into v_prof
    from public.org_members m join public.profiles p on p.user_id = m.user_id
   where m.org_id = p_org_id and m.revoked_at is null
   order by case m.role when 'owner' then 0 when 'admin' then 1 else 2 end, m.joined_at
   limit 1;
  v_owner_name := coalesce(v_prof.full_name, '');
  return jsonb_build_object(
    'id', p_org_id,
    'name', coalesce(v_prof.company_name, v_org.name),
    'phone', v_prof.company_phone,
    'email', coalesce(v_set.default_from_email, v_prof.company_email),
    'website', v_prof.company_website,
    'address', v_prof.company_address,
    'owner_name', v_owner_name,
    'owner_first_name', public.fh_first_name(v_owner_name),
    'payment_link', v_prof.payment_link,
    'review_link', coalesce(v_set.review_links->>'google', v_set.review_links->>'primary'),
    'booking_url', coalesce(v_set.app_base_url,'https://fieldhorse.app') || '/book/' || coalesce(v_set.public_key,''),
    'timezone', coalesce(v_set.timezone, 'America/Chicago'),
    'public_key', v_set.public_key
  );
end $$;

-- ---------------------------------------------------------------------------
-- Export an org's growth configuration as a portable snapshot
-- ---------------------------------------------------------------------------
create or replace function public.fh_snapshot_export(p_org_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
begin
  if auth.uid() is not null and not public.fh_is_org_manager(p_org_id) then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'snapshot_version', 1,
    'exported_at', now(),
    'name', (select name from public.organizations where id = p_org_id) || ' snapshot',
    'workflows', coalesce((select jsonb_agg(jsonb_build_object('key', w.key, 'name', w.name, 'description', w.description, 'category', w.category,
        'definition', coalesce((select v.definition from public.fh_workflow_versions v where v.id = w.active_version_id), w.draft_definition)) order by w.key)
      from public.fh_workflows w where w.org_id = p_org_id and w.status <> 'archived'), '[]'::jsonb),
    'templates', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'channel', channel, 'subject', subject, 'body', body, 'body_html', body_html, 'purpose', purpose, 'category', category) order by key)
      from public.fh_message_templates where org_id = p_org_id), '[]'::jsonb),
    'agents', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'description', description, 'model', model, 'system_prompt', system_prompt, 'autonomy', autonomy, 'tools', to_jsonb(tools), 'guardrails', guardrails) order by key)
      from public.fh_agents where org_id = p_org_id), '[]'::jsonb),
    'forms', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'fields', fields, 'settings', settings) order by key)
      from public.fh_forms where org_id = p_org_id), '[]'::jsonb),
    'booking_types', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'description', description, 'duration_min', duration_min, 'slot_interval_min', slot_interval_min,
        'buffer_before_min', buffer_before_min, 'buffer_after_min', buffer_after_min, 'min_notice_hours', min_notice_hours, 'max_days_ahead', max_days_ahead, 'max_per_day', max_per_day,
        'availability', availability, 'location_mode', location_mode, 'confirmation_sms', confirmation_sms, 'reminder_offsets_min', to_jsonb(reminder_offsets_min), 'reminder_sms', reminder_sms, 'tags', tags) order by key)
      from public.fh_booking_types where org_id = p_org_id), '[]'::jsonb),
    'segments', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'description', description, 'filter', filter, 'is_system', is_system) order by key)
      from public.fh_segments where org_id = p_org_id), '[]'::jsonb),
    'tag_defs', coalesce((select jsonb_agg(jsonb_build_object('tag', tag, 'color', color, 'description', description) order by tag)
      from public.fh_tag_defs where org_id = p_org_id), '[]'::jsonb),
    'field_defs', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'label', label, 'kind', kind, 'options', options, 'position', position) order by position)
      from public.fh_field_defs where org_id = p_org_id), '[]'::jsonb),
    'lead_sources', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'name', name, 'kind', kind) order by key)
      from public.fh_lead_sources where org_id = p_org_id), '[]'::jsonb)
  );
end $$;

-- ---------------------------------------------------------------------------
-- Import a snapshot into an org. mode = skip_existing | overwrite
-- Workflows are published and left paused so nothing fires until switched on.
-- ---------------------------------------------------------------------------
create or replace function public.fh_snapshot_import(p_org_id uuid, p_snapshot jsonb, p_mode text default 'skip_existing')
returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare x jsonb; v_id uuid; n_wf int := 0; n_t int := 0; n_a int := 0; n_f int := 0; n_b int := 0; n_s int := 0; n_tag int := 0; n_ls int := 0; v_exists boolean; v_uid uuid := auth.uid();
begin
  if auth.uid() is not null and not public.fh_is_org_manager(p_org_id) then raise exception 'not allowed'; end if;
  insert into public.fh_org_settings (org_id) values (p_org_id) on conflict (org_id) do nothing;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'tag_defs','[]'::jsonb)) loop
    insert into public.fh_tag_defs (org_id, tag, color, description) values (p_org_id, public.fh_slugify(x->>'tag'), x->>'color', x->>'description')
    on conflict (org_id, tag) do update set color = coalesce(excluded.color, public.fh_tag_defs.color), description = coalesce(excluded.description, public.fh_tag_defs.description);
    n_tag := n_tag + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'lead_sources','[]'::jsonb)) loop
    insert into public.fh_lead_sources (org_id, key, name, kind) values (p_org_id, x->>'key', x->>'name', coalesce(x->>'kind','other'))
    on conflict (org_id, key) do nothing;
    n_ls := n_ls + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'field_defs','[]'::jsonb)) loop
    insert into public.fh_field_defs (org_id, key, label, kind, options, position) values (p_org_id, x->>'key', x->>'label', coalesce(x->>'kind','text'), coalesce(x->'options','[]'::jsonb), coalesce((x->>'position')::int, 0))
    on conflict (org_id, key) do update set label = excluded.label, kind = excluded.kind, options = excluded.options, position = excluded.position;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'templates','[]'::jsonb)) loop
    select exists (select 1 from public.fh_message_templates where org_id = p_org_id and key = x->>'key') into v_exists;
    if v_exists and p_mode <> 'overwrite' then continue; end if;
    insert into public.fh_message_templates (org_id, key, name, channel, subject, body, body_html, purpose, category, is_system, created_by)
    values (p_org_id, x->>'key', x->>'name', coalesce(x->>'channel','sms'), x->>'subject', x->>'body', x->>'body_html', coalesce(x->>'purpose','transactional'), x->>'category', true, v_uid)
    on conflict (org_id, key) do update set name = excluded.name, channel = excluded.channel, subject = excluded.subject, body = excluded.body, body_html = excluded.body_html, purpose = excluded.purpose, category = excluded.category, updated_at = now();
    n_t := n_t + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'agents','[]'::jsonb)) loop
    select exists (select 1 from public.fh_agents where org_id = p_org_id and key = x->>'key') into v_exists;
    if v_exists and p_mode <> 'overwrite' then continue; end if;
    insert into public.fh_agents (org_id, key, name, description, model, system_prompt, autonomy, tools, guardrails)
    values (p_org_id, x->>'key', x->>'name', x->>'description', coalesce(x->>'model','claude-sonnet-5'), x->>'system_prompt', coalesce(x->>'autonomy','draft'),
            coalesce(array(select jsonb_array_elements_text(x->'tools')), '{propose_message}'::text[]),
            coalesce(x->'guardrails', '{"max_messages_per_client_per_day":3,"business_hours_only":true,"escalate_keywords":["lawyer","attorney","refund","sue","complaint","bbb"],"never_promise_price":true}'::jsonb))
    on conflict (org_id, key) do update set name = excluded.name, description = excluded.description, model = excluded.model, system_prompt = excluded.system_prompt, autonomy = excluded.autonomy, tools = excluded.tools, guardrails = excluded.guardrails, updated_at = now();
    n_a := n_a + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'forms','[]'::jsonb)) loop
    select exists (select 1 from public.fh_forms where org_id = p_org_id and key = x->>'key') into v_exists;
    if v_exists and p_mode <> 'overwrite' then continue; end if;
    insert into public.fh_forms (org_id, key, name, fields, settings)
    values (p_org_id, x->>'key', x->>'name', coalesce(x->'fields','[]'::jsonb), coalesce(x->'settings','{}'::jsonb))
    on conflict (org_id, key) do update set name = excluded.name, fields = excluded.fields, settings = excluded.settings, updated_at = now();
    n_f := n_f + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'booking_types','[]'::jsonb)) loop
    select exists (select 1 from public.fh_booking_types where org_id = p_org_id and key = x->>'key') into v_exists;
    if v_exists and p_mode <> 'overwrite' then continue; end if;
    insert into public.fh_booking_types (org_id, key, name, description, duration_min, slot_interval_min, buffer_before_min, buffer_after_min, min_notice_hours, max_days_ahead, max_per_day, availability, location_mode, confirmation_sms, reminder_offsets_min, reminder_sms, tags)
    values (p_org_id, x->>'key', x->>'name', x->>'description', coalesce((x->>'duration_min')::int, 60), (x->>'slot_interval_min')::int, coalesce((x->>'buffer_before_min')::int, 0), coalesce((x->>'buffer_after_min')::int, 30),
            coalesce((x->>'min_notice_hours')::int, 12), coalesce((x->>'max_days_ahead')::int, 21), coalesce((x->>'max_per_day')::int, 4), x->'availability', coalesce(x->>'location_mode','at_client_address'), x->>'confirmation_sms',
            coalesce(array(select (jsonb_array_elements_text(x->'reminder_offsets_min'))::int), '{1440,120}'::int[]), x->>'reminder_sms', coalesce(x->'tags','[]'::jsonb))
    on conflict (org_id, key) do update set name = excluded.name, description = excluded.description, duration_min = excluded.duration_min, slot_interval_min = excluded.slot_interval_min, buffer_before_min = excluded.buffer_before_min, buffer_after_min = excluded.buffer_after_min, min_notice_hours = excluded.min_notice_hours, max_days_ahead = excluded.max_days_ahead, max_per_day = excluded.max_per_day, availability = excluded.availability, location_mode = excluded.location_mode, confirmation_sms = excluded.confirmation_sms, reminder_offsets_min = excluded.reminder_offsets_min, reminder_sms = excluded.reminder_sms, tags = excluded.tags, updated_at = now();
    n_b := n_b + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'segments','[]'::jsonb)) loop
    select exists (select 1 from public.fh_segments where org_id = p_org_id and key = x->>'key') into v_exists;
    if v_exists and p_mode <> 'overwrite' then continue; end if;
    insert into public.fh_segments (org_id, key, name, description, filter, is_system)
    values (p_org_id, x->>'key', x->>'name', x->>'description', coalesce(x->'filter','{}'::jsonb), coalesce((x->>'is_system')::boolean, false))
    on conflict (org_id, key) do update set name = excluded.name, description = excluded.description, filter = excluded.filter, updated_at = now();
    n_s := n_s + 1;
  end loop;

  for x in select * from jsonb_array_elements(coalesce(p_snapshot->'workflows','[]'::jsonb)) loop
    select id into v_id from public.fh_workflows where org_id = p_org_id and key = x->>'key';
    if v_id is not null and p_mode <> 'overwrite' then continue; end if;
    if v_id is null then
      insert into public.fh_workflows (org_id, key, name, description, category, status, draft_definition, created_by)
      values (p_org_id, x->>'key', x->>'name', x->>'description', x->>'category', 'draft', coalesce(x->'definition','{}'::jsonb), v_uid)
      returning id into v_id;
    else
      update public.fh_workflows set name = x->>'name', description = x->>'description', category = x->>'category', draft_definition = coalesce(x->'definition','{}'::jsonb), updated_at = now() where id = v_id;
    end if;
    -- publish but leave paused: ready to switch on, silent until then
    begin
      perform public.fh_workflow_publish(v_id, false);
    exception when others then
      raise warning 'snapshot workflow % not published: %', x->>'key', sqlerrm;
    end;
    n_wf := n_wf + 1;
  end loop;

  return jsonb_build_object('workflows', n_wf, 'templates', n_t, 'agents', n_a, 'forms', n_f, 'booking_types', n_b, 'segments', n_s, 'tag_defs', n_tag, 'lead_sources', n_ls);
end $$;

-- Seed an org from the library. Safe to re run (skip_existing).
create or replace function public.fh_seed_growth_defaults(p_org_id uuid, p_vertical text default 'construction', p_mode text default 'skip_existing')
returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare s jsonb;
begin
  select snapshot into s from public.fh_snapshot_library where vertical = p_vertical order by updated_at desc limit 1;
  if s is null then raise exception 'no snapshot for vertical %', p_vertical; end if;
  insert into public.fh_org_settings (org_id, vertical) values (p_org_id, p_vertical) on conflict (org_id) do update set vertical = excluded.vertical;
  return public.fh_snapshot_import(p_org_id, s, p_mode);
end $$;

do $$
declare f text;
begin
  foreach f in array array['fh_snapshot_export(uuid)','fh_snapshot_import(uuid,jsonb,text)','fh_seed_growth_defaults(uuid,text,text)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('revoke all on function public.%s from anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
end $$;

